// Critically damped spring. AnimationStyle scales stiffness/damping;
// AnimationSpeed scales the time step so one control drives every motion.
struct SpringValue {
    float value = 0.0f;
    float velocity = 0.0f;
    float target = 0.0f;
    void Reset(float v) {
        value = target = v;
        velocity = 0.0f;
    }
    void Step(float totalDt, float stiffness, float damping) {
        const float kFixedDt = 0.0005f;
        while (totalDt > 0.0f) {
            float dt = std::min(totalDt, kFixedDt);
            const float displacement = value - target;
            const float acceleration = -stiffness * displacement - damping * velocity;
            velocity += acceleration * dt;
            value += velocity * dt;
            totalDt -= dt;
        }
        if (std::fabs(value - target) < 0.01f && std::fabs(velocity) < 0.01f) {
            value = target;
            velocity = 0.0f;
        }
    }
};
